// formatDate returns a UTC date as YYYY-MM-DD (zero-padded).
function formatDate(d) {
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
}

module.exports = { formatDate };

